
const $=s=>document.querySelector(s);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const symbols={search:'<circle cx="10" cy="10" r="7"/><path class="search-handle" d="m15 15 6 6"/><path class="search-heart" d="M10 13.5 6.9 10.4a2 2 0 0 1 3.1-2.5 2 2 0 0 1 3.1 2.5Z"/>',logout:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5M21 12H9"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-3 2v-9.5A8.5 8.5 0 0 1 9.5 4h3a8.5 8.5 0 0 1 8.5 7.5Z"/>',crown:'<path d="m2 8 5 4 5-8 5 8 5-4-2 12H4L2 8Z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',back:'<path d="m15 18-6-6 6-6"/>',refresh:'<path d="M3 11a9 9 0 0 1 15.36-6.36L21 7"/><path d="M21 3v4h-4"/><path d="M21 13a9 9 0 0 1-15.36 6.36L3 17"/><path d="M7 17H3v4"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="9" r="1.5"/><path d="m3 17 6-5 4 4 3-3 5 4"/>',send:'<path d="m22 2-7 20-4-9-9-4 20-7ZM11 13 22 2"/>'};
const ico=n=>'<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(symbols[n]||symbols.heart)+'</svg>';
const logo=()=>'<img src="/favicon.png?v=matchlove-20261118" width="120" height="120" alt="MatchLove — два профиля образуют сердце">';
const examples=[['Анастасия',26,'Москва',['путешествия','кофе','искусство'],'Люблю маленькие путешествия, большие завтраки и людей с чувством юмора.'],['Мария',24,'Санкт-Петербург',['архитектура','кино','прогулки'],'Коллекционирую красивые места и поводы выключить телефон.'],['Александра',27,'Казань',['книги','музыка','горы'],'Могу рассказать о последней книге. А лучше — послушаю тебя.'],['Виктория',25,'Москва',['море','фотография','йога'],'В выходные меня можно найти у воды или в поисках новых впечатлений.'],['Александр',29,'Санкт-Петербург',['кулинария','горы','музыка'],'Готовлю пасту, хожу в горы и всё ещё верю в случайные встречи.'],['Михаил',28,'Москва',['спорт','кофе','кино'],'Ищу человека, с которым даже обычный вторник станет интереснее.']].map((a,i)=>({id:'demo-'+i,name:a[0],age:a[1],city:a[2],interests:a[3],bio:a[4],demo:true,demoIndex:i}));
const S={page:'home',query:'',image:null,imageURL:'',photos:[],pendingPhotos:[],photoSaving:false,genderSaving:false,locationSaving:false,location:{city:'',enabled:false},photoError:'',me:null,logged:false,profiles:[],results:[],matches:[],social:{incoming:[],matches:[],outgoing:[]},chat:null,messages:[],processing:false,authMode:'login',error:'',chatTimer:null};
const nav=[['home','Поиск мэтчей','search'],['results','Мои мэтчи','heart'],['chats','Переписки','chat'],['profile','Профиль','user']];
async function api(path,opt={}){const r=await fetch('/api/'+path,{method:opt.method||'GET',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:opt.body?JSON.stringify(opt.body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка соединения');return d;}
function brand(){return '<button type="button" class="logo brand-home" data-nav="home" aria-label="MatchLove — Поиск мэтчей">'+logo()+'<span>Match<b>Love</b></span></button>'}
const activeNav=n=>S.page===n||(n==='profile'&&S.page==='viewProfile')||(n==='chats'&&S.page==='conversation');
function navBtn(n){return '<button class="navbtn '+(activeNav(n[0])?'active':'')+'" data-nav="'+n[0]+'">'+ico(n[2])+' '+n[1]+(n[0]==='chats'&&S.social.incoming.length?' <span class="counter">'+S.social.incoming.length+'</span>':'')+'</button>'}
function shell(body){return '<div class="app"><aside class="side">'+brand()+'<div class="side-nav">'+nav.map(navBtn).join('')+'</div><div class="side-foot">MATCHLOVE © 2026<br>Знакомства по смыслу, а не случайности.</div></aside><main class="content"><header class="top"><div class="mobilebrand">'+brand()+'</div><button class="premium" data-nav="premium">'+ico('crown')+' Подписка</button>'+(S.logged?'<button class="logout-btn" id="logout">'+ico('logout')+'<span>Выйти</span></button>':'<button type="button" class="logout-btn" data-nav="login">Войти</button>')+'</header><div class="wrap">'+body+'</div></main><nav class="bottomnav" aria-label="Основная навигация">'+nav.map(n=>'<button data-nav="'+n[0]+'" class="'+(activeNav(n[0])?'active':'')+'">'+ico(n[2])+'<span>'+n[1]+(n[0]==='chats'&&S.social.incoming.length?' ('+S.social.incoming.length+')':'')+'</span></button>').join('')+'</nav></div><div id="toast" role="status" style="position:fixed;top:85px;right:18px;z-index:50"></div>'}
function demoMatches(){
 const portrait=(name,age,index,center=false)=>'<div class="match-person '+(center?'match-center':'')+'"><div class="match-avatar portrait-'+index+'" role="img" aria-label="'+name+'"></div><strong>'+name+', '+age+'</strong></div>';
 const link=(score,best=false)=>'<div class="match-link '+(best?'best-link':'')+'"><svg viewBox="0 0 120 55" aria-hidden="true"><path class="connection-base" d="M2 34 Q60 -10 118 34"/><defs><radialGradient id="firefly-'+(best?'pink':'green')+'"><stop offset="0" stop-color="'+(best?'#ffe4ed':'#f1ffd9')+'" stop-opacity=".95"/><stop offset=".15" stop-color="'+(best?'#ff9fbc':'#c4ff86')+'" stop-opacity=".8"/><stop offset=".42" stop-color="'+(best?'#ff527d':'#a3ff66')+'" stop-opacity=".35"/><stop offset="1" stop-color="'+(best?'#ff527d':'#a3ff66')+'" stop-opacity="0"/></radialGradient></defs><g class="connection-dot"><animateMotion dur="4s" repeatCount="indefinite" path="'+(best?'M2 34 Q60 -10 118 34':'M118 34 Q60 -10 2 34')+'"/><g class="firefly-light"><circle r="18" fill="url(#firefly-'+(best?'pink':'green')+')"/><circle class="firefly-core" r="4" fill="url(#firefly-'+(best?'pink':'green')+')"/></g></g></svg><span class="connection-heart">♥</span><strong>'+score+'</strong><small>совпадение</small></div>';
 const detail=(name,items)=>'<div class="match-breakdown"><strong>Алиса + '+name+'</strong>'+items.map(([label,value])=>'<span>'+label+' <b>'+value+'%</b></span>').join('')+'</div>';
 return '<section class="match-preview" aria-label="Как ИИ подбирает совпадения"><div class="match-network">'+portrait('Даниил',28,4)+link('95%')+portrait('Алиса',29,2,true)+link('100%',true)+portrait('Марк',31,1)+'</div><div class="match-details">'+detail('Даниил',[['Походы в горы','94'],['Спонтанные поездки','91'],['Серьёзные отношения','100']])+detail('Марк',[['Вечерние прогулки','100'],['Чувство юмора','100'],['Серьёзные отношения','100']])+'</div></section>'
}

function accountGenderControl(){if(!S.logged)return '';const gender=S.me?.gender;return '<div class="account-gender-control"><span id="gender-label">Мой пол</span><details class="gender-dropdown" id="gender-picker" '+(S.genderSaving?'aria-disabled="true"':'')+'><summary id="account-gender" aria-labelledby="gender-label gender-value" '+(S.genderSaving?'tabindex="-1"':'')+'><span id="gender-value">'+(gender==='male'?'Мужчина':gender==='female'?'Женщина':'Выбери пол')+'</span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m4 6 4 4 4-4"/></svg></summary><div class="gender-options">'+[['female','Женщина'],['male','Мужчина']].map(([value,label])=>'<button type="button" data-gender="'+value+'" aria-pressed="'+(gender===value)+'" '+(S.genderSaving?'disabled':'')+'>'+label+(gender===value?'<span aria-hidden="true">✓</span>':'')+'</button>').join('')+'</div></details><small>'+(!gender?'Укажи пол, чтобы начать подбор':gender==='male'?'По умолчанию ищем женщин':'По умолчанию ищем мужчин')+'. Другие пожелания можно указать в описании.</small></div>';}

async function saveAccountGender(gender){if(S.genderSaving)return;const owner=S.me?.id;S.query=$('#about')?.value??S.query;S.genderSaving=true;render();try{const saved=await api('account-gender',{method:'PATCH',body:{gender}});if(S.me?.id!==owner)return;S.me.gender=saved.gender;S.results=[];}catch(error){if(S.me?.id===owner)toast(error.message)}finally{if(S.me?.id===owner){S.genderSaving=false;render();}}}
let locationChoiceMemory='',guestLocation=null;
function locationChoice(){try{return localStorage.getItem('matchlove.geo-choice')||locationChoiceMemory;}catch{return locationChoiceMemory;}}
function rememberLocationChoice(choice){locationChoiceMemory=choice;try{localStorage.setItem('matchlove.geo-choice',choice);}catch{}}
function maybeShowLocationPrompt(){
 if(S.page!=='home'||S.location.enabled||locationChoice()||!navigator.geolocation||document.querySelector('dialog[open]'))return;
 const dialog=document.createElement('dialog');dialog.className='location-dialog';dialog.setAttribute('aria-labelledby','location-dialog-title');
 dialog.innerHTML='<div class="location-dialog-art" aria-hidden="true"><svg viewBox="0 0 80 90"><path d="M40 83S11 51 11 32a29 29 0 0 1 58 0c0 19-29 51-29 51Z"/><circle cx="40" cy="31" r="10"/></svg><span>♥</span></div><h2 id="location-dialog-title">Твой человек может быть рядом</h2><p>Разреши геолокацию, чтобы учитывать расстояние и находить людей поближе.</p><button type="button" class="btn btn-primary btn-wide" data-enable-geo>Включить геолокацию</button><button type="button" class="link" data-later-geo>Позже</button><p class="location-dialog-error" role="status"></p>';
 document.body.append(dialog);dialog.tabIndex=-1;dialog.showModal();dialog.focus({preventScroll:true});
 dialog.addEventListener('cancel',()=>rememberLocationChoice('later'));
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 dialog.querySelector('[data-later-geo]').onclick=()=>{rememberLocationChoice('later');dialog.close();};
 dialog.querySelector('[data-enable-geo]').onclick=async()=>{
  const button=dialog.querySelector('[data-enable-geo]'),owner=S.me?.id;button.disabled=true;button.textContent='Определяем местоположение…';dialog.querySelector('.location-dialog-error').textContent='';
  try{
   const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,maximumAge:300000,timeout:15000}));
   if(!dialog.isConnected)return;
   const body={latitude:position.coords.latitude,longitude:position.coords.longitude,consent:true};
   rememberLocationChoice('allowed');
   if(S.logged&&S.me?.id===owner)await updateLocation(body);else guestLocation=body;
   dialog.close();
  }catch(error){
   if(!dialog.isConnected)return;
   if(error.code===1)rememberLocationChoice('denied');
   dialog.querySelector('.location-dialog-error').textContent=error.code===1?'Доступ не разрешён. Можно продолжить без геолокации и указать город в описании.':'Не удалось определить местоположение. Попробуй ещё раз или продолжи без геолокации.';
   button.disabled=false;button.textContent='Попробовать ещё раз';
  }
 };
}
async function refreshGrantedLocation(){
 const owner=S.me?.id;if(!S.logged||(!S.location.enabled&&locationChoice()!=='allowed')||!navigator.geolocation)return;
 try{if(navigator.permissions?.query){const permission=await navigator.permissions.query({name:'geolocation'});if(permission.state!=='granted')return;}
 const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,maximumAge:300000,timeout:10000}));
 if(S.me?.id!==owner)return;
 const saved=await api('location',{method:'PATCH',body:{latitude:position.coords.latitude,longitude:position.coords.longitude,consent:true}});if(S.me?.id===owner)S.location=saved;
 }catch{} // Keep the saved location when offline or permission is no longer available.
}
async function restoreLocation(){if(!S.logged)return;const owner=S.me?.id;try{const row=await api('location');if(S.me?.id===owner){S.location=row;if(guestLocation){const pending=guestLocation;guestLocation=null;await updateLocation(pending);}else void refreshGrantedLocation();}}catch{}}
async function updateLocation(body,method='PATCH'){const owner=S.me?.id;const row=await api('location',{method,body});if(S.me?.id===owner){S.location=row;S.results=[];}}
function photoGallery(){
 return '<div class="photo-gallery"><div class="photo-gallery-head"><label class="photo-upload">'+ico('photo')+' <span>'+(S.photoSaving?'Сохраняем фото…':'Добавить фото')+'</span><input type="file" id="myphoto" accept="image/jpeg,image/png,image/webp,image/gif" multiple '+(S.photoSaving||S.photos.length>=30?'disabled':'')+'></label></div>'+(S.photos.length?'<div class="photo-grid">'+S.photos.map(p=>'<div class="gallery-photo '+(p.main?'is-main':'')+'"><img src="'+esc(p.url)+'" alt="'+(p.main?'Главное фото анкеты':'Фото анкеты')+'">'+(p.main?'<span class="main-photo-badge">Главное</span>':'<button type="button" class="set-main-photo" data-photo-main="'+esc(p.id)+'" '+(S.photoSaving?'disabled':'')+'>Сделать главным</button>')+'<button type="button" class="delete-photo" data-photo-delete="'+esc(p.id)+'" aria-label="Удалить фото" '+(S.photoSaving?'disabled':'')+'>×</button></div>').join('')+'</div>':S.imageURL?'<img class="photo-preview" src="'+esc(S.imageURL)+'" alt="Выбранное фото">':'')+''+(S.photoError?'<span class="photo-save-error" role="status">'+esc(S.photoError)+'</span>':'')+'</div>';
}
function pageHome(){return '<div class="hero"><div><h1><span class="red">Точный мэтч</span> — Твой человек.</h1></div>'+(!S.logged?demoMatches():'')+'</div><section class="panel searchbox"><div class="sectiontop"><label class="match-intro" for="about">Расскажи о себе — ИИ найдёт людей, с которыми совпадают желания и интересы.</label></div><textarea id="about" minlength="100" aria-label="Расскажи о себе и кого ищешь" role="combobox" aria-autocomplete="list" aria-haspopup="listbox" aria-expanded="false" aria-controls="tag-suggestions" placeholder="Например: Мне 28, живу в Москве, люблю путешествия, кино и спонтанные поездки. Хочу познакомиться с человеком, который ценит юмор, близость и умеет наслаждаться жизнью…">'+esc(S.query)+'</textarea><div id="tag-suggestions" class="tag-suggestions" role="listbox" aria-label="Подсказки интересов" hidden></div>'+photoGallery()+accountGenderControl()+'<button class="btn btn-primary btn-wide" style="margin-top:20px" id="find" '+(S.photoSaving||S.genderSaving||S.locationSaving?'disabled':'')+'>'+ico('heart')+' Найти мои мэтчи '+ico('arrow')+'</button></section>'}
function tokenize(t){return (String(t||'').toLowerCase().replace(/ё/g,'е').match(/[а-яa-z]{4,}/g)||[]).map(w=>w.replace(/(ами|ями|ого|ему|ыми|ими|иях|ать|ять|ение|ость|ами|ями|ов|ев|ами|ами|ой|ая|ые|ий|ый|ого|ами|ах|ях|ей|ие|ое|у|а|ы|и|е)$/,'')).filter(w=>w.length>=3)}
function rankPeople(list){const words=new Set(tokenize(S.query)),scored=list.map((p,i)=>{const profile=tokenize([p.bio||'',...(p.interests||[]),p.city||''].join(' '));const common=[...new Set(profile)].filter(x=>words.has(x));const overlap=common.length;const score=Math.min(96,Math.max(30,45+overlap*13+(p.interests||[]).filter(v=>tokenize(v).some(t=>words.has(t))).length*8));const explanation=common.length?'Общее: '+common.slice(0,4).join(', '):'Попробуйте добавить больше интересов для точного сравнения';return {...p,score,explanation,originalIndex:i}});return scored.sort((a,b)=>b.score-a.score||a.originalIndex-b.originalIndex)}
function face(p){if(p.demo)return '<div class="pic sprite" style="--x:'+(p.demoIndex%3)+';--y:'+Math.floor(p.demoIndex/3)+'"></div>';const url=p.media?.find(m=>m.url&&!m.locked)?.url;return '<div class="pic">'+(url?'<img src="'+esc(url)+'" alt="'+esc(p.name)+'" loading="lazy">':'<div style="height:100%;display:grid;place-items:center;font-size:55px">♥</div>')+'</div>'}
const matchPercent=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number(n)||0);
function person(p){const incoming=S.social.incoming.some(x=>x.id===p.id),liked=S.social.outgoing.some(x=>x.id===p.id)||S.social.matches.some(x=>x.id===p.id),matched=S.social.matches.some(x=>x.id===p.id);return '<article class="person" tabindex="0" data-profile="'+esc(p.id)+'" aria-label="Открыть анкету '+esc(p.name)+'"><div style="position:relative">'+face(p)+'<span class="matchpill">'+matchPercent(p.score)+'% '+(p.aiEvaluated?'AI-совпадение':'предварительно')+'</span></div><div class="person-info"><h3>'+esc(p.name)+(p.age?', '+esc(p.age):'')+'</h3>'+(p.city?'<div class="city">'+esc(p.city)+'</div>':'')+'<div class="match-contributions">'+(p.matches||[]).filter(m=>Number(m.points)>0).map(m=>'<span class="match-contribution"><span title="'+esc(m.label)+'">'+esc(m.category==='gender'?'Пол':m.category==='age'&&m.label==='Близкий возраст'?'Возраст':m.label)+'</span>'+' <b>+'+matchPercent(m.points)+'%</b></span>').join('')+'</div>'+(incoming?'<div class="liked-me">♥ '+esc(p.name)+' уже поставил(а) тебе лайк!</div>':'')+'<button type="button" class="btn '+(matched?'btn-green':liked?'btn-ghost':'btn-primary')+' btn-wide" style="margin-top:14px;padding:11px" data-like="'+esc(p.id)+'" '+(liked&&!matched?'disabled':'')+'>'+(matched?'♥ Написать':liked?'♥ Лайк отправлен':incoming?'♥ Ответить взаимностью':'♡ Нравится')+'</button></div></article>'}

function results(){if(!S.results.length)return '<div class="page-head"><h2>Мои мэтчи<span style="color:var(--red)">.</span></h2></div><div class="empty"><h3>Пока нет результатов</h3><p>Расскажи о себе, и здесь появится твоя последняя подборка.</p><button class="btn btn-primary" style="margin-top:22px" data-nav="home">Начать поиск</button></div>';return '<div class="page-head"><h2>Люди, с которыми <span style="color:var(--green)">совпало</span></h2><p>Подборка по интересам и описанию. Самые близкие совпадения — первыми.</p><button class="btn btn-green" id="update" style="margin-top:20px">'+ico('refresh')+' Обновить мэтчи</button></div><div class="cardgrid">'+S.results.map(person).join('')+'</div>'}
function loading(){
 const photo=S.imageURL||S.me?.profile?.media?.find(m=>m.url&&!m.locked&&(!m.kind||m.kind==='photo'))?.url;
 const points=[[42,58],[150,26],[258,58],[258,202],[150,234],[42,202]];
 const rays=points.map(([x,y],i)=>{const dx=x-150,dy=y-130,length=Math.hypot(dx,dy),ux=dx/length,uy=dy/length;const path='M'+(150+ux*37).toFixed(2)+' '+(130+uy*37).toFixed(2)+' L'+(x-ux*24).toFixed(2)+' '+(y-uy*24).toFixed(2);const duration=6.2+i*.37,begin=(-i*1.13).toFixed(2)+'s';
 const stop=(offset,red,green,opacity)=>'<stop offset="'+offset+'" stop-color="'+red+'" stop-opacity="'+opacity+'"><animate attributeName="stop-color" values="'+red+';'+green+'" calcMode="discrete" dur="'+(duration*2)+'s" begin="'+begin+'" repeatCount="indefinite"/></stop>';
 return '<defs><radialGradient id="search-firefly-'+i+'">'+stop('0','#fff1f6','#f1ffdf','.95')+stop('.18','#ff9fbc','#c4ff86','.7')+stop('.48','#ff527d','#b2ff7b','.25')+stop('1','#ff527d','#b2ff7b','0')+'</radialGradient></defs><path class="search-ray" d="'+path+'"/><g class="connection-dot"><animateMotion dur="'+duration+'s" begin="'+begin+'" repeatCount="indefinite" path="'+path+'"/><g class="firefly-light"><circle r="12" fill="url(#search-firefly-'+i+')"/></g></g>';}).join('');
 return '<section class="search-wait" aria-busy="true" aria-labelledby="search-title"><div class="search-constellation"><svg viewBox="0 0 300 260" aria-hidden="true">'+rays+'</svg>'+points.map(([x,y],i)=>'<span class="search-placeholder placeholder-'+i+'" style="left:'+(x/3)+'%;top:'+(y/2.6)+'%;--delay:'+(-i*.3)+'s" aria-hidden="true"><span class="placeholder-art"></span></span>').join('')+'<div class="search-self">'+(photo?'<img src="'+esc(photo)+'" alt="Твоё главное фото">':'<span class="search-self-fallback" aria-label="Твоя анкета">'+ico('user')+'</span>')+'</div></div><h2 id="search-title">ИИ подбирает самые<br><span class="red">подходящие совпадения</span></h2><p id="scantext" role="status" aria-live="polite">Сравниваем твои интересы и пожелания с анкетами…</p></section>'
}

function price(){return '<div class="page-head"><div class="eyebrow">MATCHLOVE PLUS</div><h2>Больше возможностей.<br><span style="color:var(--red)">Больше совпадений.</span></h2><p>Подписки появятся после подключения оплаты.</p></div><div class="pricegrid"><section class="price"><div class="eyebrow">БАЗОВЫЙ</div><h3 style="margin-top:13px">Free</h3><strong>0 ₽</strong><ul><li>Описание себя</li><li>Поиск анкет</li><li>Список совпадений</li></ul><button class="btn btn-ghost btn-wide" data-nav="home">Продолжить бесплатно</button></section><section class="price hot"><div class="eyebrow">БОЛЬШЕ ИСКР</div><h3 style="margin-top:13px">MatchLove Plus</h3><strong>Скоро</strong><ul><li>Расширенный AI-подбор</li><li>Подбор по внешности</li><li>Дополнительные фильтры</li></ul><button class="btn btn-primary btn-wide" disabled>Скоро в продаже</button></section></div>'}
function login(){const reg=S.authMode==='register';return '<div class="login"><h2 style="margin-top:12px">'+(reg?'Создать аккаунт':'С возвращением')+'<span style="color:var(--red)">.</span></h2><p class="lead" style="margin:10px 0 20px">Войди, чтобы сохранять свои знакомства и переписки.</p><section class="panel"><form id="auth" class="stack">'+(reg?'<fieldset class="registration-gender"><legend>Твой пол</legend><label><input type="radio" name="gender" value="female" required> Женщина</label><label><input type="radio" name="gender" value="male" required> Мужчина</label></fieldset>':'')+'<label>Email<input class="field" name="email" type="email" autocomplete="email" required></label><label>Пароль<input class="field" name="password" type="password" minlength="'+(reg?10:1)+'" autocomplete="'+(reg?'new-password':'current-password')+'" required></label>'+(reg?'<label style="display:flex;gap:10px;align-items:center"><input type="checkbox" name="adult" required>Мне исполнилось 18 лет</label><label style="display:flex;gap:10px;align-items:center"><input type="checkbox" name="terms" required>Согласен с правилами сервиса</label><label>Код приглашения (если есть)<input class="field" name="invite"></label>':'')+'<button class="btn btn-primary btn-wide" type="submit">'+(reg?'Зарегистрироваться':'Войти')+'</button></form><p id="auth-error" class="notice" style="color:var(--pink);margin-top:12px"></p><button class="link" id="toggleauth">'+(reg?'Уже есть аккаунт? Войти':'Нет аккаунта? Регистрация')+'</button></section></div>'}
function chats(){if(!S.logged)return '<div class="empty"><h3>Войди, чтобы переписываться</h3><p>Сообщения доступны после взаимной симпатии.</p><button class="btn btn-primary" style="margin-top:22px" data-nav="login">Войти</button></div>';const incoming=S.social.incoming||[];const liked= incoming.length?'<section class="inbound-likes"><h2 style="font-size:23px;margin-bottom:13px">♥ Тебя лайкнули <span class="counter">'+incoming.length+'</span></h2><div class="incoming-grid">'+incoming.map(p=>'<div class="incoming-row"><strong>'+esc(p.name)+'</strong><small>'+esc(p.city||'Город не указан')+'</small><button type="button" class="btn btn-primary" data-like="'+esc(p.id)+'">♥ Взаимный лайк</button></div>').join('')+'</div></section>':'';return ''+liked+'<div class="chatlist">'+(S.matches.length?S.matches.map(p=>'<button class="chatrow" data-chat="'+esc(p.id)+'"><div class="body"><strong>♥ '+esc(p.name)+'</strong><small>Взаимный мэтч — открыть переписку</small></div>'+ico('arrow')+'</button>').join(''):'<div class="empty"><h3>Пока нет взаимных мэтчей</h3><p>Когда симпатия совпадёт, вы сможете переписываться.</p></div>')+'</div>'}

function conversation(){const p=S.matches.find(x=>x.id===S.chat)||S.profiles.find(x=>x.id===S.chat);return '<div class="chatbox"><div class="chathead"><button data-nav="chats" aria-label="Назад">'+ico('back')+'</button><button type="button" class="chat-profile-name" data-profile="'+esc(S.chat)+'">'+esc(p?.name||'Открыть анкету')+'</button></div><div class="messages" id="message-list">'+S.messages.map(m=>'<div class="bubble '+(m.sender===S.me?.id?'mine':'')+'">'+esc(m.body||'Вложение')+'</div>').join('')+'</div><form class="compose" id="compose"><input name="message" class="field" placeholder="Напиши сообщение…" maxlength="3000" required><button class="btn btn-primary" aria-label="Отправить">'+ico('send')+'</button></form></div>'}
function render(){captureProfileDraft();clearTagSuggestions();const pages={home:pageHome,results,loading,login,chats,premium:price,conversation,profile:profilePage,viewProfile:profilePage};$('#app').innerHTML=S.page==='loading'?'<main class="search-fullscreen"><div class="search-brand">'+brand()+'</div>'+loading()+'</main>':shell((pages[S.page]||pageHome)());document.title='MatchLove — знакомства по смыслу';initProfileCarousel();requestAnimationFrame(maybeShowLocationPrompt);}
function toast(message){const t=$('#toast');if(!t)return;t.textContent=message;t.style.cssText='position:fixed;top:85px;right:18px;z-index:50;background:#301b26;color:#fff;border:2px solid #ff355f;border-radius:14px;padding:14px 20px;max-width:320px;font-size:13px;box-shadow:0 20px 40px #0009';setTimeout(()=>{if(t.isConnected)t.remove()},3600)}
async function go(page){if(page==='profile'){await openProfile();return;}S.query=$('#about')?.value??S.query;clearInterval(S.chatTimer);S.chatTimer=null;if(['chats','results'].includes(page)&&S.logged)await loadMatches();S.page=page;render();window.scrollTo(0,0)}
async function loadMatches(){try{S.social=await api('ml-social');S.matches=S.social.matches||[]}catch{S.social={incoming:[],matches:[],outgoing:[]};S.matches=[]}}
function applyGallery(saved){S.photos=saved.photos||[];S.imageURL=saved.url||'';}
async function restoreSearchPhoto(){
 if(!S.logged||S.image)return;const owner=S.me?.id;
 try{const saved=await api('search-photo-info');if(S.me?.id===owner&&!S.image)applyGallery(saved);}catch{if(S.me?.id===owner)S.photoError='Не удалось загрузить сохранённые фото. Обнови страницу.';}
}
async function saveSearchPhoto(){
 if(!S.logged||!S.image||S.photoSaving)return false;
 const owner=S.me?.id,queue=[S.image,...S.pendingPhotos],preview=S.imageURL;S.photoSaving=true;S.photoError='';render();
 try{let saved;
 while(queue.length){const form=new FormData();form.append('file',queue[0]);const response=await fetch('/api/search-photo',{method:'POST',credentials:'same-origin',body:form});saved=await response.json();if(!response.ok)throw Error(saved.error||'Не удалось сохранить фото');if(S.me?.id!==owner)return false;queue.shift();S.photos=saved.photos||[];}
 if(preview.startsWith('blob:'))URL.revokeObjectURL(preview);applyGallery(saved);S.image=null;S.pendingPhotos=[];return true;
 }catch(error){if(S.me?.id===owner){S.image=queue[0]||null;S.pendingPhotos=queue.slice(1);S.photoError=error.message;}return false;}finally{if(S.me?.id===owner){S.photoSaving=false;S.query=$('#about')?.value??S.query;render();}}
}
async function changePhoto(id,method){
 if(S.photoSaving)return;const owner=S.me?.id;S.query=$('#about')?.value??S.query;S.photoSaving=true;S.photoError='';render();
 try{const saved=await api('search-photo',{method,body:{id}});if(S.me?.id===owner)applyGallery(saved);}catch(error){if(S.me?.id===owner)S.photoError=error.message;}finally{if(S.me?.id===owner){S.photoSaving=false;render();}}
}
async function boot(){try{const m=await api('me');S.me=m;S.logged=!!m?.id;if(S.logged){await restoreLocation();render();await restoreSearchPhoto();try{S.profiles=(await api('discover?')).profiles||[]}catch{}await loadMatches();try{const saved=await api('ai-match');S.results=(saved.results||[]);S.query=$('#about')?.value.trim()?$('#about').value:saved.source||'';}catch{}}}catch{}render()}
async function search(){
 if(S.processing||S.photoSaving||S.genderSaving||S.locationSaving)return;
 const field=$('#about');S.query=field?field.value:S.query;
 let useManual=false;
 if(!S.query.trim()&&S.logged){try{const own=await api('ml-profile');useManual=['self','wanted'].some(side=>Object.entries(own.profile[side]||{}).some(([key,value])=>!['gender','preferences'].includes(key)&&(Array.isArray(value)?value.length:!!value)));}catch{}}
 if(S.query.trim().length<100&&!useManual){toast('Опиши себя или желаемого партнёра подробнее — от 100 символов, либо заполни профиль');return;}
 if(!S.logged){S.page='login';render();toast('Войди, чтобы сохранить анкету и найти реальные совпадения');return;}
 if(!['male','female'].includes(S.me?.gender)){S.page='home';render();toast('Укажи свой пол перед поиском');$('#account-gender')?.focus();return;}
 if(S.image&&!await saveSearchPhoto()){toast(S.photoError||'Не удалось сохранить фото. Попробуй ещё раз.');return;}
 S.processing=true;S.page='loading';render();let tick=0;
 const timer=setInterval(()=>{tick++;const label=$('#scantext');if(label)label.textContent=['Сравниваем твои интересы и пожелания с анкетами…','Ищем взаимный интерес — важно, чтобы вы подошли друг другу…','Оцениваем, что именно у вас совпадает…'][tick%3];},2800);
 try{
  if(!useManual){const result=await api('ai-match',{method:'POST',body:{text:S.query,confirmAdult:true}});if(!result.ok)throw Error('Не удалось сохранить анкету');}
  const matched=await api('ai-match');
  S.results=(matched.results||[]);
  await loadMatches();S.page='results';render();
 }catch(err){S.page='home';render();toast(err.message||'Не удалось выполнить поиск')}
 finally{clearInterval(timer);S.processing=false;}
}
async function openChat(id){S.chat=id;S.messages=[];S.page='conversation';render();await refreshChat();S.chatTimer=setInterval(()=>{if(document.visibilityState==='visible')refreshChat()},5000)}
async function refreshChat(){if(!S.chat)return;try{const data=await api('ml-chat?target='+encodeURIComponent(S.chat));S.messages=data.messages||[];if(S.page==='conversation'){const list=$('#message-list');if(list){list.innerHTML=S.messages.map(m=>'<div class="bubble '+(m.sender===S.me?.id?'mine':'')+'">'+esc(m.body||'Вложение')+'</div>').join('');list.scrollTop=list.scrollHeight}}}catch(e){toast(e.message)}}
async function logout(){
 const button=$('#logout');if(button)button.disabled=true;
 try{await api('auth/logout',{method:'POST',body:{}});if(S.chatTimer)clearInterval(S.chatTimer);if(S.imageURL)URL.revokeObjectURL(S.imageURL);
 profileView=null;profileDraft=null;Object.assign(S,{page:'home',query:'',image:null,imageURL:'',photos:[],pendingPhotos:[],photoSaving:false,genderSaving:false,locationSaving:false,location:{city:'',enabled:false},photoError:'',me:null,logged:false,profiles:[],results:[],matches:[],social:{incoming:[],matches:[],outgoing:[]},chat:null,messages:[],processing:false,authMode:'login',error:'',chatTimer:null});render();toast('Ты вышел из аккаунта');
 }catch(error){if(button)button.disabled=false;toast(error.message)}
}
document.addEventListener('click',async e=>{const suggestion=e.target.closest('[data-suggestion]');if(suggestion){applyTagSuggestion(Number(suggestion.dataset.suggestion));return}if(!e.target.closest('#about')&&!e.target.closest('#tag-suggestions'))clearTagSuggestions();const gender=e.target.closest('[data-gender]');if(gender){await saveAccountGender(gender.dataset.gender);return}if(!e.target.closest('.gender-dropdown'))$('#gender-picker')?.removeAttribute('open');const main=e.target.closest('[data-photo-main]');if(main){await changePhoto(main.dataset.photoMain,'PATCH');return}const remove=e.target.closest('[data-photo-delete]');if(remove){await changePhoto(remove.dataset.photoDelete,'DELETE');return}if(e.target.closest('#logout')){await logout();return}const n=e.target.closest('[data-nav]');if(n){await go(n.dataset.nav);return}if(e.target.closest('#find')){search();return}if(e.target.closest('#update')){search();return}if(e.target.closest('#toggleauth')){S.authMode=S.authMode==='login'?'register':'login';render();return}const chat=e.target.closest('[data-chat]');if(chat){await openChat(chat.dataset.chat);return}const like=e.target.closest('[data-like]');if(like){const id=like.dataset.like;if(!S.logged){await go('login');return}if(S.social.matches.some(p=>p.id===id)){await openChat(id);return}like.disabled=true;try{const response=await api('ml-like',{method:'POST',body:{target:id}});await loadMatches();if(response.matched){toast('♥ Взаимная симпатия! Можно переписываться.');await openChat(id)}else{toast('♥ Симпатия отправлена!');render()}}catch(error){like.disabled=false;toast(error.message)}return}});

document.addEventListener('change',async e=>{if(e.target.id==='myphoto'){
 if(S.photoSaving)return;const files=Array.from(e.target.files||[]);if(!files.length)return;
 if(S.photos.length+files.length>30)return toast('Можно загрузить до 30 фото');
 if(files.some(file=>!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)))return toast('Выбери фото JPEG, PNG, WebP или GIF');if(files.some(file=>file.size>8*1024*1024))return toast('Каждое фото должно быть не больше 8 МБ');
 if(S.imageURL.startsWith('blob:'))URL.revokeObjectURL(S.imageURL);S.image=files[0];S.pendingPhotos=files.slice(1);if(!S.photos.length)S.imageURL=URL.createObjectURL(files[0]);S.photoError='';S.query=$('#about')?.value||S.query;render();
 if(S.logged)await saveSearchPhoto();
}});

document.addEventListener('submit',async e=>{if(e.target.id==='auth'){e.preventDefault();const d=new FormData(e.target);try{await api('auth/'+S.authMode,{method:'POST',body:{email:d.get('email'),gender:d.get('gender'),password:d.get('password'),adult:d.get('adult')==='on',terms:d.get('terms')==='on',invite:d.get('invite')||''}});S.me=await api('me');S.logged=!!S.me?.id;if(S.image)await saveSearchPhoto();else await restoreSearchPhoto();await restoreLocation();try{S.profiles=(await api('discover?')).profiles||[]}catch{}await loadMatches();await go('home');toast('Добро пожаловать в MatchLove')}catch(err){const box=$('#auth-error');if(box)box.textContent=err.message}return}if(e.target.id==='compose'){e.preventDefault();const input=e.target.elements.message;const value=input.value.trim();if(!value)return;try{await api('ml-chat',{method:'POST',body:{target:S.chat,body:value}});input.value='';await refreshChat()}catch(err){toast(err.message)}}});
let suggestionTimer=null,suggestionAbort=null,suggestionSequence=0,suggestionItems=[],suggestionContext=null,activeSuggestion=-1;
function clearTagSuggestions(){if(suggestionTimer)clearTimeout(suggestionTimer);suggestionTimer=null;suggestionAbort?.abort();suggestionAbort=null;suggestionSequence++;suggestionItems=[];suggestionContext=null;activeSuggestion=-1;const list=$('#tag-suggestions');if(list){list.hidden=true;list.innerHTML='';}const field=$('#about');field?.setAttribute('aria-expanded','false');field?.removeAttribute('aria-activedescendant');}
function tagContext(field){const end=field.selectionStart??field.value.length,before=field.value.slice(0,end);if(!before.trim())return {start:end,end,query:''};const match=before.match(/(?:я\s+)?(?:люблю|обожаю)\s+[^,.!?;\n]{0,60}$/i)||before.match(/[\p{L}\p{N}-]{2,}$/u);return match?{start:end-match[0].length,end,query:match[0]}:null;}
function highlightSuggestion(){const field=$('#about');document.querySelectorAll('#tag-suggestions [data-suggestion]').forEach((button,i)=>{button.setAttribute('aria-selected',String(i===activeSuggestion));});if(activeSuggestion>=0)field?.setAttribute('aria-activedescendant','tag-choice-'+activeSuggestion);else field?.removeAttribute('aria-activedescendant');}
function requestTagSuggestions(field){S.query=field.value;clearTagSuggestions();const context=tagContext(field);if(!context)return;const sequence=suggestionSequence;suggestionTimer=setTimeout(async()=>{const controller=new AbortController();suggestionAbort=controller;try{const r=await fetch('/api/tag-suggestions',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({q:context.query}),signal:controller.signal});if(!r.ok)return;const data=await r.json();if(sequence!==suggestionSequence||$('#about')!==field)return;const list=$('#tag-suggestions');if(!list)return;suggestionItems=(data.suggestions||[]).slice(0,6);suggestionContext=context;list.innerHTML=suggestionItems.map((item,i)=>'<button type="button" role="option" aria-selected="false" id="tag-choice-'+i+'" data-suggestion="'+i+'">'+esc(item.text)+'</button>').join('');list.hidden=!suggestionItems.length;field.setAttribute('aria-expanded',String(!!suggestionItems.length));}catch(error){if(error.name!=='AbortError')clearTagSuggestions();}},180);}
function applyTagSuggestion(index){const field=$('#about'),item=suggestionItems[index],context=suggestionContext;if(!field||!item||!context)return;field.setRangeText(item.text,context.start,context.end,'end');S.query=field.value;clearTagSuggestions();field.focus({preventScroll:true});}
document.addEventListener('input',e=>{if(e.target.id==='about')requestTagSuggestions(e.target);});
document.addEventListener('focusin',e=>{if(e.target.id==='about'&&!e.target.value.trim())requestTagSuggestions(e.target);});
document.addEventListener('pointerdown',e=>{if(e.target.closest('[data-suggestion]'))e.preventDefault();});
document.addEventListener('keydown',e=>{if(e.target.id!=='about'||!suggestionItems.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();activeSuggestion=(activeSuggestion+(e.key==='ArrowDown'?1:activeSuggestion<0?suggestionItems.length:-1)+suggestionItems.length)%suggestionItems.length;highlightSuggestion();}else if(e.key==='Enter'&&activeSuggestion>=0){e.preventDefault();applyTagSuggestion(activeSuggestion);}else if(e.key==='Escape'){e.preventDefault();clearTagSuggestions();}});
const profileFields=[['name','Имя'],['bio','Описание'],['age_min','Возраст от'],['age_max','Возраст до'],['location','Город'],['gender','Кого ищу'],['goal','Цель знакомства'],['interests','Интересы и хобби'],['habits','Привычки'],['personality','Характер'],['profession','Работа'],['appearance','Внешность'],['sexual_preferences','Интимные предпочтения']];
let profileView=null,profileReturn='results',profileTab='self',profileDraft=null,profileSaving=false,profileGeneration=0;
function captureProfileDraft(){const form=$('#profile-edit');if(!form||!profileDraft||Number(form.dataset.generation)!==profileGeneration)return;const data=new FormData(form),side=profileDraft[form.dataset.side];for(const [key] of profileFields){if(!data.has(key))continue;const value=data.get(key);if(key==='interests'){let values;try{values=JSON.parse(value);if(!Array.isArray(values))values=[];}catch{values=[];}const pending=$('#new-interest')?.value.trim();if(pending&&!values.some(v=>v.toLowerCase()===pending.toLowerCase()))values.push(pending);side.interests=values;continue;}side[key]=['age_min','age_max'].includes(key)?(value===''?null:Number(value)):['goal','interests','habits','personality','profession','appearance','sexual_preferences'].includes(key)?String(value).split(/[,;\n]/).map(v=>v.trim()).filter(Boolean):String(value);}if(form.dataset.side==='self'&&data.has('age_min'))side.age_max=side.age_min;}
function profileCarousel(photos){
 if(!photos.length)return '<div class="profile-no-photo">'+ico('user')+'</div>';
 const loop=photos.length>1,slides=loop?[photos.at(-1),...photos,photos[0]]:photos;
 return '<div class="profile-photo-wrap"><div class="profile-carousel" data-count="'+photos.length+'" tabindex="0" aria-label="Фотографии анкеты">'+slides.map((p,i)=>{const clone=loop&&(i===0||i===slides.length-1);return '<img src="'+esc(p.url)+'" alt="'+(clone?'':'Фото '+(loop?i:i+1))+'" '+(clone?'aria-hidden="true"':'')+' loading="'+(i<2?'eager':'lazy')+'">';}).join('')+'</div>'+(loop?'<div class="profile-photo-controls"><button type="button" data-photo-step="-1" aria-label="Предыдущее фото"><svg viewBox="0 0 24 40" aria-hidden="true"><path d="M20 3 4 20l16 17"/></svg></button><button type="button" data-photo-step="1" aria-label="Следующее фото"><svg viewBox="0 0 24 40" aria-hidden="true"><path d="m4 3 16 17L4 37"/></svg></button></div>':'')+'</div>';
}
function initProfileCarousel(){
 const carousel=$('.profile-carousel'),count=Number(carousel?.dataset.count);if(!carousel||count<2)return;
 const jump=index=>carousel.scrollTo({left:index*carousel.clientWidth,behavior:'instant'});
 requestAnimationFrame(()=>{if(carousel.isConnected)jump(1);});
 let timer,current=1,width=carousel.clientWidth;const settle=()=>{if(!carousel.isConnected)return;const index=Math.round(carousel.scrollLeft/carousel.clientWidth);current=index===0?count:index===count+1?1:index;if(index!==current)jump(current);};
 const resize=new ResizeObserver(()=>{if(!carousel.isConnected){resize.disconnect();return;}if(carousel.clientWidth!==width){width=carousel.clientWidth;jump(current);}});resize.observe(carousel);
 carousel.addEventListener('scroll',()=>{clearTimeout(timer);timer=setTimeout(settle,180);},{passive:true});
 carousel.addEventListener('scrollend',settle);
 carousel.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();stepProfilePhoto(event.key==='ArrowLeft'?-1:1);}});
}
function stepProfilePhoto(step){const carousel=$('.profile-carousel');if(!carousel)return;const count=Number(carousel.dataset.count),width=carousel.clientWidth;let index=Math.round(carousel.scrollLeft/width);if(index===0){index=count;carousel.scrollTo({left:index*width,behavior:'instant'});}else if(index===count+1){index=1;carousel.scrollTo({left:width,behavior:'instant'});}carousel.scrollTo({left:(index+step)*width,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}
function interestEditor(values){return '<div class="interest-editor"><input type="hidden" name="interests" value="'+esc(JSON.stringify(values))+'"><div class="profile-tags editable-interest-tags" tabindex="0" aria-label="Интересы — прокрути строку">'+values.map((value,i)=>'<span><span>'+esc(value)+'</span><button type="button" data-remove-interest="'+i+'" aria-label="Удалить интерес '+esc(value)+'">×</button></span>').join('')+'</div><div class="interest-add"><input type="text" maxlength="80" id="new-interest" placeholder="Добавить интерес" aria-label="Новый интерес"><button type="button" id="add-interest">Добавить</button></div></div>';}
function changeInterest(remove){captureProfileDraft();const values=profileDraft[profileTab].interests||[];if(remove!==undefined)values.splice(remove,1);const hidden=$('#profile-edit [name=interests]');if(hidden)hidden.value=JSON.stringify(values);const input=$('#new-interest');if(input)input.value='';render();$('#new-interest')?.focus({preventScroll:true});}
function searchAgeControl(p){return '<fieldset class="search-age-control"><legend>Возраст кого ищем</legend><div class="search-age-values">'+[['age_min','От'],['age_max','До']].map(([key,label])=>'<div><span>'+label+'</span><input type="hidden" name="'+key+'" value="'+esc(p[key]??'')+'"><button type="button" data-age-picker="'+key+'" aria-label="'+label+': '+(p[key]??'не задан')+'">'+(p[key]??'—')+'</button></div>').join('')+'</div></fieldset>';}
function openAgePicker(focusKey){
 captureProfileDraft();const ages=[null,...Array.from({length:83},(_,i)=>i+18)],selection={age_min:profileDraft.wanted.age_min??null,age_max:profileDraft.wanted.age_max??null};
 const dialog=document.createElement('dialog');dialog.className='age-dialog';dialog.setAttribute('aria-label','Возраст кого ищем');
 dialog.innerHTML='<div class="age-dialog-head"><button type="button" data-age-cancel>Отмена</button><strong>Возраст кого ищем</strong><button type="button" data-age-done>Готово</button></div><div class="age-wheels">'+[['age_min','От'],['age_max','До']].map(([key,label])=>'<div><span>'+label+'</span><div class="age-wheel" data-age-wheel="'+key+'" tabindex="0" role="listbox" aria-label="'+label+'">'+ages.map((age,i)=>'<button type="button" tabindex="-1" role="option" id="wheel-'+key+'-'+i+'" data-age-index="'+i+'" aria-selected="false">'+(age??'—')+'</button>').join('')+'</div></div>').join('')+'</div><p class="age-picker-error" role="status"></p>';
 document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 for(const wheel of dialog.querySelectorAll('[data-age-wheel]')){
  const key=wheel.dataset.ageWheel;
  const select=()=>{const index=Math.max(0,Math.min(ages.length-1,Math.round(wheel.scrollTop/40)));selection[key]=ages[index];wheel.querySelectorAll('[role=option]').forEach((row,i)=>{row.setAttribute('aria-selected',String(i===index));});wheel.setAttribute('aria-activedescendant','wheel-'+key+'-'+index);};
  wheel.scrollTop=Math.max(0,ages.indexOf(selection[key]))*40;select();
  wheel.addEventListener('scroll',select,{passive:true});
  wheel.addEventListener('click',event=>{const row=event.target.closest('[data-age-index]');if(row)wheel.scrollTo({top:Number(row.dataset.ageIndex)*40,behavior:'smooth'});});
  wheel.addEventListener('keydown',event=>{if(['ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();let index=Math.round(wheel.scrollTop/40)+(event.key==='ArrowDown'?1:-1);if(event.key==='Home')index=0;if(event.key==='End')index=ages.length-1;wheel.scrollTo({top:Math.max(0,Math.min(ages.length-1,index))*40,behavior:'instant'});select();}});
 }
 dialog.querySelector('[data-age-cancel]').onclick=()=>dialog.close();
 dialog.querySelector('[data-age-done]').onclick=()=>{
  for(const wheel of dialog.querySelectorAll('[data-age-wheel]')){const index=Math.max(0,Math.min(ages.length-1,Math.round(wheel.scrollTop/40)));selection[wheel.dataset.ageWheel]=ages[index];}
  if(selection.age_min!==null&&selection.age_max!==null&&selection.age_min>selection.age_max){dialog.querySelector('.age-picker-error').textContent='Возраст «От» должен быть не больше возраста «До».';return;}
  for(const [key,value] of Object.entries(selection))$('#profile-edit [name='+key+']').value=value??'';
  dialog.close();captureProfileDraft();render();$('[data-age-picker='+focusKey+']')?.focus({preventScroll:true});
 };
 dialog.querySelector('[data-age-wheel='+focusKey+']').focus({preventScroll:true});
}
function profilePage(){
 if(!S.logged)return '<div class="empty"><h3>Войди, чтобы открыть профиль</h3><button class="btn btn-primary" data-nav="login">Войти</button></div>';
 if(!profileView)return '<p role="status">Загружаем анкету…</p>';
 const v=profileView,own=v.own,p=(own?profileDraft:v.profile)[profileTab]||{};
 const tabs='<div class="profile-tabs" role="tablist" aria-label="Раздел анкеты">'+[['self','О себе'],['wanted','Кого ищу']].map(([key,label])=>'<button type="button" role="tab" aria-selected="'+(profileTab===key)+'" data-profile-tab="'+key+'">'+label+'</button>').join('')+'</div>';
 const photos=own?S.photos.map(photo=>({...photo})):v.photos;
 const head='<div class="profile-heading">'+(!own?'<button type="button" class="link" id="profile-back">'+ico('back')+' Назад</button>':'<h2>Мой профиль</h2>')+'</div>';
 if(own)return '<section class="profile-page">'+head+'<p class="profile-hint">Заполни анкету вручную или поручи это ИИ: расскажи о себе и кого ищешь в разделе «Поиск мэтчей». ИИ разложит описание по категориям. Ручные исправления сохранятся при следующих поисках.</p>'+tabs+profileCarousel(photos)+'<details class="profile-photos-edit"><summary>Добавить и настроить фото</summary>'+photoGallery()+'</details>'+(profileTab==='self'?accountGenderControl():'')+'<p class="profile-hint">'+(S.me?.gender==='female'?'С чем-то не согласна?':S.me?.gender==='male'?'С чем-то не согласен?':'Хочешь что-то исправить?')+' Исправь поля ниже. Для подбора используются возраст, город и пункты по категориям.</p><form id="profile-edit" data-generation="'+profileGeneration+'" data-side="'+profileTab+'" class="profile-form">'+profileFields.filter(([key])=>profileTab==='self'?!['gender','age_max'].includes(key):key!=='name').map(([key,label])=>{
 if(profileTab==='wanted'&&key==='age_max')return '';if(profileTab==='wanted'&&key==='age_min')return searchAgeControl(p);
 const value=p[key]??'',locked=Object.hasOwn(v.locked?.[profileTab]||{},key),isList=Array.isArray(value),age=['age_min','age_max'].includes(key);
 let control=key==='interests'?interestEditor(Array.isArray(value)?value:[]):key==='gender'?'<select name="gender" class="field"><option value="" '+(!value?'selected':'')+'>По умолчанию</option><option value="all" '+(value==='all'?'selected':'')+'>Любой пол</option><option value="female" '+(value==='female'?'selected':'')+'>Женщин</option><option value="male" '+(value==='male'?'selected':'')+'>Мужчин</option></select>':key==='bio'?'<textarea name="bio" maxlength="1200" rows="4">'+esc(value)+'</textarea>':isList?'<textarea name="'+key+'" maxlength="2500" rows="2" placeholder="Через запятую">'+esc(value.join(', '))+'</textarea>':'<input class="field" name="'+key+'" '+(age?'type="number" min="18" max="100"':'maxlength="'+(key==='name'?60:90)+'"')+' value="'+esc(value)+'">';
 return '<label class="profile-field-'+key+'">'+(profileTab==='self'&&key==='age_min'?'Возраст':label)+(locked?'<small class="manual-mark">Исправлено вручную</small>':'')+control+'</label>';
 }).join('')+'<button type="submit" class="btn btn-primary" '+(profileSaving?'disabled':'')+'>'+(profileSaving?'Сохраняем…':'Сохранить анкету')+'</button><p id="profile-error" role="status"></p></form></section>';
 const details=profileFields.filter(([key])=>!['name','bio','age_min','age_max'].includes(key)&&!(profileTab==='self'&&key==='location')).map(([key,label])=>{
  const value=p[key];if(!value||(Array.isArray(value)&&!value.length))return '';
  return '<div class="profile-detail"><h3>'+ (key==='gender'&&profileTab==='self'?'Пол':label)+'</h3>'+(Array.isArray(value)?'<div class="profile-tags">'+value.map(t=>'<span>'+esc(t)+'</span>').join(''):'<p>'+esc(key==='gender'?value==='male'?(profileTab==='self'?'Мужчина':'Мужчин'):value==='female'?(profileTab==='self'?'Женщина':'Женщин'):value:value)+'</p>')+'</div>';
 }).join('');
 const age=p.age_min?(p.age_max&&p.age_max!==p.age_min?p.age_min+'–'+p.age_max:p.age_min):null;
 return '<section class="profile-page">'+head+tabs+profileCarousel(photos)+'<h2>'+esc(v.name)+(profileTab==='self'&&age?', '+esc(age):'')+'</h2>'+(profileTab==='self'&&v.city?'<p class="profile-city">'+esc(v.city)+'</p>':'')+(profileTab==='wanted'&&age?'<p>Возраст: '+esc(age)+'</p>':'')+(p.bio?'<p class="profile-bio">'+esc(p.bio)+'</p>':'')+details+'</section>';
}
async function openProfile(id){
 if(!S.logged){await go('login');return;}
 captureProfileDraft();S.query=$('#about')?.value??S.query;
 if(S.page!=='profile'&&S.page!=='viewProfile')profileReturn=S.page;
 try{const view=await api('ml-profile'+(id?'?user='+encodeURIComponent(id):''));clearInterval(S.chatTimer);S.chatTimer=null;profileGeneration++;profileView=view;profileDraft=structuredClone(view.profile);profileTab='self';S.page=view.own?'profile':'viewProfile';render();window.scrollTo(0,0);}catch(error){toast(error.message);}
}
async function saveProfile(){
 if(profileSaving||!profileView?.own)return;
 captureProfileDraft();const body={};
 for(const side of ['self','wanted']){const changes={};for(const [key] of profileFields){if(side==='self'&&key==='gender'||side==='wanted'&&key==='name')continue;const before=profileView.profile[side]?.[key]??null,after=profileDraft[side]?.[key]??null;if(JSON.stringify(before)!==JSON.stringify(after))changes[key]=after;}if(Object.keys(changes).length)body[side]=changes;}
 if(!Object.keys(body).length){toast('Изменений нет');return;}
 profileSaving=true;render();
 try{const saved=await api('ml-profile',{method:'PATCH',body});profileGeneration++;profileView.profile=saved.profile;profileView.locked=saved.locked;profileDraft=structuredClone(saved.profile);profileView.name=saved.profile.self.name||profileView.name;S.results=[];toast('Анкета сохранена');}catch(error){toast(error.message);}finally{profileSaving=false;render();}
}
document.addEventListener('submit',e=>{if(e.target.id==='profile-edit'){e.preventDefault();void saveProfile();}});
document.addEventListener('click',async e=>{
 const age=e.target.closest('[data-age-picker]');if(age){openAgePicker(age.dataset.agePicker);return;}
 if(e.target.closest('#add-interest')){changeInterest();return;}
 const interest=e.target.closest('[data-remove-interest]');if(interest){changeInterest(Number(interest.dataset.removeInterest));return;}
 const tab=e.target.closest('[data-profile-tab]');if(tab){captureProfileDraft();profileTab=tab.dataset.profileTab;render();return;}
 const photo=e.target.closest('[data-photo-step]');if(photo){stepProfilePhoto(Number(photo.dataset.photoStep));return;}
 if(e.target.closest('#profile-back')){if(profileReturn==='conversation')await openChat(S.chat);else await go(profileReturn);return;}
 if(e.target.closest('[data-like],[data-chat],[data-photo-main],[data-photo-delete]'))return;
 const card=e.target.closest('[data-profile]');if(card)await openProfile(card.dataset.profile);
});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[data-profile]')){e.preventDefault();void openProfile(e.target.dataset.profile);}});

document.addEventListener('keydown',event=>{if(event.target.id==='new-interest'&&event.key==='Enter'){event.preventDefault();changeInterest();}});
window.addEventListener('hashchange',()=>{});boot();

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#gender-picker')?.hasAttribute('open')){$('#gender-picker').removeAttribute('open');$('#account-gender')?.focus();}});
